def compute(vars):
    maturity_amount = vars["v1"]
    interest_rate_percent = vars["v2"]
    interest_amount = maturity_amount * interest_rate_percent / 100

    return {
        "value": interest_amount,
        "trace": {
            "maturity_amount": maturity_amount,
            "interest_rate_percent": interest_rate_percent,
            "interest_amount": interest_amount,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
